(function (global) {

    function loadScript(src) {
  
      return new Promise(function (resolve, reject) {
  
        var s = document.createElement("script");
  
        s.src = src;
        s.async = false;
  
        s.onload = function () {
  
          var timeout = 3000;
          var start = Date.now();
  
          function waitUntilReady() {
  
            if (global.myMotion) {
              resolve();
            }
            else if (Date.now() - start > timeout) {
              reject(new Error("myMotion not registered from " + src));
            }
            else {
              requestAnimationFrame(waitUntilReady);
            }
  
          }
  
          waitUntilReady();
  
        };
  
        s.onerror = reject;
  
        document.head.appendChild(s);
  
      });
  
    }
  
  
    async function init() {
  
      if (!global.gsap) {
        console.error("❌ GSAP belum diload");
        return;
      }
  
      try {
  
        console.log("Loading SplitMotion modules...");
  
        await loadScript(
          "https://cdn.jsdelivr.net/gh/yuzuyyy/splitMotion@main/dist/split-motion.min.js"
        );
  
        await loadScript(
          "https://cdn.jsdelivr.net/gh/yuzuyyy/splitMotion@main/dist/scramble.min.js"
        );
  
        await loadScript(
          "https://cdn.jsdelivr.net/gh/yuzuyyy/splitMotion@main/dist/pixelTwo.min.js"
        );
  
        await loadScript(
          "https://cdn.jsdelivr.net/gh/yuzuyyy/splitMotion@main/dist/marquee.min.js"
        );
  
        console.log("✅ Bundle loaded");
  
        global.SplitMotionBundleReady = true;
  
        global.myMotion.init();
  
      }
      catch (e) {
  
        console.error("❌ Loader error:", e);
  
      }
  
    }
  
  
    if (document.readyState === "complete")
      init();
    else
      window.addEventListener("load", init);
  
  })(window);

